import{_ as o,c as a,o as s,j as r,Y as i,t as n}from"./chunks/framework.BNTND4LZ.js";const k=JSON.parse('{"title":"git-remote-ext | x-cmd man (git man1) | Bridge smart transport to external command.","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-remote-ext - Bridge smart transport to external command.","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-remote-ext | x-cmd man (git man1) | Bridge smart transport to external command."}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-remote-ext - Bridge smart transport to external command."}]]},"headers":[],"params":{"isMan":true,"man":"git-remote-ext","category":"git man1","desc":"Bridge smart transport to external command."},"relativePath":"git/man1/git-remote-ext.md","filePath":"git/man1/[man].md"}'),p={name:"git/man1/git-remote-ext.md"},l={class:"visually-hidden"};function m(t,e,h,c,u,d){return s(),a("div",null,[r("h1",l,n(t.$params.man),1),e[0]||(e[0]=i('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-remote-ext - Bridge smart transport to external command.</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">k</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ext::&lt;command&gt;[ &lt;arguments&gt;...]&quot;</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This remote helper uses the specified <em>&lt;command&gt;</em> to connect to a remote Git server.</p><p>Data written to stdin of the specified <em>&lt;command&gt;</em> is assumed to be sent to a git:// server, git-upload-pack, git-receive-pack or git-upload-archive (depending on situation), and data read from stdout of &lt;command&gt; is assumed to be received from the same service.</p><p>Command and arguments are separated by an unescaped space.</p><p>The following sequences have a special meaning:</p><p>&#39;% &#39;</p><blockquote><p>Literal space in command or argument.</p></blockquote><p><em>%%</em></p><blockquote><p>Literal percent sign.</p></blockquote><p><em>%s</em></p><blockquote><p>Replaced with name (receive-pack, upload-pack, or upload-archive) of the service Git wants to invoke.</p></blockquote><p><em>%S</em></p><blockquote><p>Replaced with long name (git-receive-pack, git-upload-pack, or git-upload-archive) of the service Git wants to invoke.</p></blockquote><p><em>%G</em> (must be the first characters in an argument)</p><blockquote><p>This argument will not be passed to <em>&lt;command&gt;</em>. Instead, it will cause the helper to start by sending git:// service requests to the remote side with the service field set to an appropriate value and the repository field set to rest of the argument. Default is not to send such a request.</p><p>This is useful if remote side is git:// server accessed over some tunnel.</p></blockquote><p><em>%V</em> (must be first characters in argument)</p><blockquote><p>This argument will not be passed to <em>&lt;command&gt;</em>. Instead it sets the vhost field in the git:// service request (to rest of the argument). Default is not to send vhost in such request (if sent).</p></blockquote><h2 id="environment-variables" tabindex="-1">ENVIRONMENT VARIABLES <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;ENVIRONMENT VARIABLES&quot;">​</a></h2><p>GIT_TRANSLOOP_DEBUG</p><blockquote><p>If set, prints debugging information about various reads/writes.</p></blockquote><h2 id="environment-variables-passed-to-command" tabindex="-1">ENVIRONMENT VARIABLES PASSED TO COMMAND <a class="header-anchor" href="#environment-variables-passed-to-command" aria-label="Permalink to &quot;ENVIRONMENT VARIABLES PASSED TO COMMAND&quot;">​</a></h2><p>GIT_EXT_SERVICE</p><blockquote><p>Set to long name (git-upload-pack, etc...) of service helper needs to invoke.</p></blockquote><p>GIT_EXT_SERVICE_NOPREFIX</p><blockquote><p>Set to long name (upload-pack, etc...) of service helper needs to invoke.</p></blockquote><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>This remote helper is transparently used by Git when you use commands such as &quot;git fetch &lt;URL&gt;&quot;, &quot;git clone &lt;URL&gt;&quot;, , &quot;git push &lt;URL&gt;&quot; or &quot;git remote add &lt;nick&gt; &lt;URL&gt;&quot;, where &lt;URL&gt; begins with <strong>ext::</strong>. Examples:</p><p>&quot;ext::ssh -i /home/foo/.ssh/somekey user@host.example %S <em>foo/repo</em>&quot;</p><blockquote><p>Like host.example:foo/repo, but use /home/foo/.ssh/somekey as keypair and user as user on remote side. This avoids needing to edit .ssh/config.</p></blockquote><p>&quot;ext::socat -t3600 - ABSTRACT-CONNECT:/git-server %G/somerepo&quot;</p><blockquote><p>Represents repository with path /somerepo accessible over git protocol at abstract namespace address /git-server.</p></blockquote><p>&quot;ext::git-server-alias foo %G/repo&quot;</p><blockquote><p>Represents a repository with path /repo accessed using the helper program &quot;git-server-alias foo&quot;. The path to the repository and type of request are not passed on the command line but as part of the protocol stream, as usual with git:// protocol.</p></blockquote><p>&quot;ext::git-server-alias foo %G/repo %Vfoo&quot;</p><blockquote><p>Represents a repository with path /repo accessed using the helper program &quot;git-server-alias foo&quot;. The hostname for the remote server passed in the protocol stream will be &quot;foo&quot; (this allows multiple virtual Git servers to share a link-level address).</p></blockquote><p>&quot;ext::git-server-alias foo %G/repo% with% spaces %Vfoo&quot;</p><blockquote><p>Represents a repository with path <strong>/repo with spaces</strong> accessed using the helper program &quot;git-server-alias foo&quot;. The hostname for the remote server passed in the protocol stream will be &quot;foo&quot; (this allows multiple virtual Git servers to share a link-level address).</p></blockquote><p>&quot;ext::git-ssl foo.example /bar&quot;</p><blockquote><p>Represents a repository accessed using the helper program &quot;git-ssl foo.example /bar&quot;. The type of request can be determined by the helper using environment variables (see above).</p></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>gitremote-helpers</strong>(7)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>',47))])}const q=o(p,[["render",m]]);export{k as __pageData,q as default};
